public class CustomHelpProviderTests
{
[Fact]
public void LoadEmbeddedFont_WithNonExistentFile_ThrowsFileNotFoundException()
{
    // Arrange
    var settings = new CommandAppSettings(); // Assuming CommandAppSettings is available
    var customHelpProvider = new CustomHelpProvider(settings);

    // Act & Assert
    var exception = Assert.Throws<FileNotFoundException>(() => 
    {
        // We're using reflection to access the private method
        var method = typeof(CustomHelpProvider).GetMethod("LoadEmbeddedFont", 
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
